insert into model_guides (model_id, job_key, kind, title, difficulty, time_min, tools, parts, steps, video_url, source) values
  ('2019-ford-f-150-2.7-4wd', 'oil_change', 'maintenance', 'Change engine oil and filter', 'medium', 45, array['Socket set', 'Oil filter wrench', 'Drain pan', 'Funnel', 'Jack stands or ramps']::text[], array['6 qt 5W-30', 'Oil filter', 'Drain plug gasket']::text[], array['Warm the engine 2 minutes, then shut it off and park on level ground.', 'Raise the vehicle safely on ramps or jack stands.', 'Remove the drain plug and let the oil drain into the pan.', 'Remove the old filter (cartridge-style spin-on filter under the front of the engine), oil the new gasket and fit it hand-tight.', 'Refit the drain plug with a new gasket and torque to spec.', 'Fill with 6 qt of 5W-30, run 30 s, check for leaks, recheck the dipstick.', 'Reset the oil-life monitor in the instrument cluster menu.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', 'engine_air_filter', 'maintenance', 'Replace engine air filter', 'easy', 10, array['Screwdriver (some clips)']::text[], array['Engine air filter']::text[], array['Open the hood and find the air box next to the engine.', 'Release the clips on the air box lid.', 'Lift out the old filter and wipe debris from the box.', 'Seat the new filter with the rubber edge all the way round.', 'Close the lid and lock every clip.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', 'cabin_air_filter', 'maintenance', 'Replace cabin air filter', 'easy', 15, array['None']::text[], array['Cabin air filter']::text[], array['Open the glove box, release the stops, and remove the filter cover behind it.', 'Slide out the old filter and note the airflow arrow.', 'Insert the new filter with the arrow pointing the same way.', 'Refit the cover or glove box.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', 'tire_rotation', 'maintenance', 'Rotate tires', 'medium', 45, array['Floor jack', 'Jack stands', 'Lug wrench', 'Torque wrench', 'Tire gauge']::text[], '{}'::text[], array['Loosen the lug nuts a half turn on all four wheels.', 'Raise the vehicle and support it on jack stands.', 'Move the wheels front-to-rear on the same side (rearward cross for 4WD trucks).', 'Hand-tighten, lower, then torque the lug nuts in a star pattern.', 'Set all tires to 35 psi cold, per the door-jamb placard.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', 'wiper_blades', 'maintenance', 'Replace wiper blades', 'easy', 10, array['None']::text[], array['22 in + 22 in blades']::text[], array['Lift the wiper arm off the windshield.', 'Press the release tab and slide the old blade off the hook.', 'Slide the new blade on until it clicks.', 'Lower the arm gently and test the wipers.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', 'battery', 'repair', 'Test and replace the 12V battery', 'medium', 30, array['Multimeter', '10 mm wrench', 'Battery terminal brush']::text[], array['12V battery (same group size)']::text[], array['With the engine off for an hour, measure the battery: 12.6 V is full, below 12.2 V is weak.', 'Disconnect the negative terminal first, then the positive.', 'Remove the hold-down and lift the battery out.', 'Clean the terminals, fit the new battery and the hold-down.', 'Connect positive first, then negative. Most parts stores recycle the old battery.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', 'brake_pads_front', 'repair', 'Replace front brake pads', 'hard', 90, array['Floor jack', 'Jack stands', 'Socket set', 'C-clamp or piston tool', 'Torque wrench']::text[], array['Front brake pads', 'Brake cleaner', 'Caliper grease']::text[], array['Raise the front and remove the wheels.', 'Remove the caliper bolts and hang the caliper; never let it hang by the hose.', 'Remove the old pads, check rotor thickness against the minimum stamped on it.', 'Push the piston back, fit the new pads with grease on the contact points.', 'Refit the caliper and torque the bolts, refit the wheels.', 'Pump the brake pedal until firm before driving, then bed in the pads with gentle stops.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2019-ford-f-150-2.7-4wd', null, 'repair', 'Check 2.7L EcoBoost oil consumption and PCV', 'medium', 30, array['Flashlight', 'Clean rag']::text[], '{}'::text[], array['Check the dipstick at every fill-up for 1,000 mi and log the level.', 'More than 1 qt per 3,000 mi is excessive; note any blue smoke at start-up.', 'Inspect the PCV hose and valve on the driver side for oil residue or cracks.', 'Look for oil seeping at the composite oil pan seam.', 'Bring the log to a Ford dealer: a leaking oil pan or PCV fault may be covered by the 5 yr / 60k powertrain warranty.']::text[], 'https://www.carcarekiosk.com/videos/Ford', 'assumption: drafted from the 2019 Ford F-150 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'oil_change', 'maintenance', 'Change engine oil and filter', 'medium', 45, array['Socket set', 'Oil filter wrench', 'Drain pan', 'Funnel', 'Jack stands or ramps']::text[], array['8 qt 0W-20 dexos1 Gen 2', 'Oil filter', 'Drain plug gasket']::text[], array['Warm the engine 2 minutes, then shut it off and park on level ground.', 'Raise the vehicle safely on ramps or jack stands.', 'Remove the drain plug and let the oil drain into the pan.', 'Remove the old filter (spin-on filter at the front of the engine, passenger side), oil the new gasket and fit it hand-tight.', 'Refit the drain plug with a new gasket and torque to spec.', 'Fill with 8 qt of 0W-20 dexos1 Gen 2, run 30 s, check for leaks, recheck the dipstick.', 'Reset the oil-life monitor in the instrument cluster menu.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'engine_air_filter', 'maintenance', 'Replace engine air filter', 'easy', 10, array['Screwdriver (some clips)']::text[], array['Engine air filter']::text[], array['Open the hood and find the air box next to the engine.', 'Release the clips on the air box lid.', 'Lift out the old filter and wipe debris from the box.', 'Seat the new filter with the rubber edge all the way round.', 'Close the lid and lock every clip.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'cabin_air_filter', 'maintenance', 'Replace cabin air filter', 'easy', 15, array['None']::text[], array['Cabin air filter']::text[], array['Open the glove box, push in its sides, and lower it to reach the filter door.', 'Slide out the old filter and note the airflow arrow.', 'Insert the new filter with the arrow pointing the same way.', 'Refit the cover or glove box.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'tire_rotation', 'maintenance', 'Rotate tires', 'medium', 45, array['Floor jack', 'Jack stands', 'Lug wrench', 'Torque wrench', 'Tire gauge']::text[], '{}'::text[], array['Loosen the lug nuts a half turn on all four wheels.', 'Raise the vehicle and support it on jack stands.', 'Move the wheels front-to-rear on the same side (rearward cross for 4WD trucks).', 'Hand-tighten, lower, then torque the lug nuts in a star pattern.', 'Set all tires to 35 psi cold, per the door-jamb placard.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'wiper_blades', 'maintenance', 'Replace wiper blades', 'easy', 10, array['None']::text[], array['22 in + 22 in blades']::text[], array['Lift the wiper arm off the windshield.', 'Press the release tab and slide the old blade off the hook.', 'Slide the new blade on until it clicks.', 'Lower the arm gently and test the wipers.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'battery', 'repair', 'Test and replace the 12V battery', 'medium', 30, array['Multimeter', '10 mm wrench', 'Battery terminal brush']::text[], array['12V battery (same group size)']::text[], array['With the engine off for an hour, measure the battery: 12.6 V is full, below 12.2 V is weak.', 'Disconnect the negative terminal first, then the positive.', 'Remove the hold-down and lift the battery out.', 'Clean the terminals, fit the new battery and the hold-down.', 'Connect positive first, then negative. Most parts stores recycle the old battery.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'brake_pads_front', 'repair', 'Replace front brake pads', 'hard', 90, array['Floor jack', 'Jack stands', 'Socket set', 'C-clamp or piston tool', 'Torque wrench']::text[], array['Front brake pads', 'Brake cleaner', 'Caliper grease']::text[], array['Raise the front and remove the wheels.', 'Remove the caliper bolts and hang the caliper; never let it hang by the hose.', 'Remove the old pads, check rotor thickness against the minimum stamped on it.', 'Push the piston back, fit the new pads with grease on the contact points.', 'Refit the caliper and torque the bolts, refit the wheels.', 'Pump the brake pedal until firm before driving, then bed in the pads with gentle stops.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', null, 'repair', 'Spot Dynamic Fuel Management lifter trouble', 'shop_only', 20, array['OBD-II scanner']::text[], '{}'::text[], array['Listen at idle for a steady ticking from the top of the engine that rises with RPM.', 'Note any misfire, check-engine light, or rough idle at low speed.', 'Scan for codes P0300 to P0308 (misfires) and P3400-range cylinder deactivation codes.', 'Do not keep driving with a flashing check-engine light.', 'This repair (lifters, sometimes camshaft) is shop-only; ask whether the 5 yr / 60k powertrain warranty covers it.']::text[], 'https://www.carcarekiosk.com/videos/Chevrolet', 'assumption: drafted from the 2020 Chevrolet Silverado 1500 owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'oil_change', 'maintenance', 'Change engine oil and filter', 'medium', 45, array['Socket set', 'Oil filter wrench', 'Drain pan', 'Funnel', 'Jack stands or ramps']::text[], array['4.8 qt 0W-16', 'Oil filter', 'Drain plug gasket']::text[], array['Warm the engine 2 minutes, then shut it off and park on level ground.', 'Raise the vehicle safely on ramps or jack stands.', 'Remove the drain plug and let the oil drain into the pan.', 'Remove the old filter (spin-on filter at the front of the engine, reached from below), oil the new gasket and fit it hand-tight.', 'Refit the drain plug with a new gasket and torque to spec.', 'Fill with 4.8 qt of 0W-16, run 30 s, check for leaks, recheck the dipstick.', 'Reset the oil-life monitor in the instrument cluster menu.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'engine_air_filter', 'maintenance', 'Replace engine air filter', 'easy', 10, array['Screwdriver (some clips)']::text[], array['Engine air filter']::text[], array['Open the hood and find the air box next to the engine.', 'Release the clips on the air box lid.', 'Lift out the old filter and wipe debris from the box.', 'Seat the new filter with the rubber edge all the way round.', 'Close the lid and lock every clip.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'cabin_air_filter', 'maintenance', 'Replace cabin air filter', 'easy', 15, array['None']::text[], array['Cabin air filter']::text[], array['Open the glove box, unhook the damper, squeeze the sides to lower it, and open the filter cover.', 'Slide out the old filter and note the airflow arrow.', 'Insert the new filter with the arrow pointing the same way.', 'Refit the cover or glove box.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'tire_rotation', 'maintenance', 'Rotate tires', 'medium', 45, array['Floor jack', 'Jack stands', 'Lug wrench', 'Torque wrench', 'Tire gauge']::text[], '{}'::text[], array['Loosen the lug nuts a half turn on all four wheels.', 'Raise the vehicle and support it on jack stands.', 'Move the wheels front-to-rear on the same side (rearward cross for AWD).', 'Hand-tighten, lower, then torque the lug nuts in a star pattern.', 'Set all tires to 35 psi cold, per the door-jamb placard.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'wiper_blades', 'maintenance', 'Replace wiper blades', 'easy', 10, array['None']::text[], array['26 in + 16 in blades']::text[], array['Lift the wiper arm off the windshield.', 'Press the release tab and slide the old blade off the hook.', 'Slide the new blade on until it clicks.', 'Lower the arm gently and test the wipers.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'battery', 'repair', 'Test and replace the 12V battery', 'medium', 30, array['Multimeter', '10 mm wrench', 'Battery terminal brush']::text[], array['12V battery (same group size)']::text[], array['With the engine off for an hour, measure the battery: 12.6 V is full, below 12.2 V is weak.', 'Disconnect the negative terminal first, then the positive.', 'Remove the hold-down and lift the battery out.', 'Clean the terminals, fit the new battery and the hold-down.', 'Connect positive first, then negative. Most parts stores recycle the old battery.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', 'brake_pads_front', 'repair', 'Replace front brake pads', 'hard', 90, array['Floor jack', 'Jack stands', 'Socket set', 'C-clamp or piston tool', 'Torque wrench']::text[], array['Front brake pads', 'Brake cleaner', 'Caliper grease']::text[], array['Raise the front and remove the wheels.', 'Remove the caliper bolts and hang the caliper; never let it hang by the hose.', 'Remove the old pads, check rotor thickness against the minimum stamped on it.', 'Push the piston back, fit the new pads with grease on the contact points.', 'Refit the caliper and torque the bolts, refit the wheels.', 'Pump the brake pedal until firm before driving, then bed in the pads with gentle stops.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check'),
  ('2021-toyota-rav4-hybrid-awd', null, 'repair', 'Fix a dead 12V battery on the RAV4 Hybrid', 'medium', 30, array['Multimeter', 'Jump pack', '10 mm wrench']::text[], array['12V AGM battery if replacing']::text[], array['A dead 12V battery means the car will not show READY; the hybrid battery is usually fine.', 'Open the hood and jump from the 12V battery terminals as the owner manual shows.', 'Once READY, leave it on for 30 minutes; the hybrid system charges the 12V battery.', 'If it dies again within days, test it: below 12.4 V after a night parked means replace with an AGM battery.', 'Avoid leaving accessories or a dashcam on while the car is off.']::text[], 'https://www.carcarekiosk.com/videos/Toyota/RAV4/2021', 'assumption: drafted from the 2021 Toyota RAV4 Hybrid owner manual and maintenance schedule; needs a person''s check');
insert into model_common_issues (model_id, title, symptom, typical_cost_low_cents, typical_cost_high_cents, source) values
  ('2019-ford-f-150-2.7-4wd', 'Oil pan leak (composite pan)', 'Oil spots under the engine, low oil between changes', 40000, 90000, 'https://www.nhtsa.gov/vehicle/2019/FORD/F-150 (owner complaints); cost range is an assumption'),
  ('2019-ford-f-150-2.7-4wd', '10-speed transmission harsh or erratic shifts', 'Clunk or hard shift between low gears', 15000, 400000, 'https://www.nhtsa.gov/vehicle/2019/FORD/F-150 (owner complaints); cost range is an assumption'),
  ('2019-ford-f-150-2.7-4wd', 'Oil consumption / PCV', 'Low oil warning, blue smoke at start-up', 10000, 150000, 'https://www.nhtsa.gov/vehicle/2019/FORD/F-150 (owner complaints); cost range is an assumption'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'Lifter failure on cylinder deactivation (AFM/DFM)', 'Ticking at idle, misfire, check-engine light', 250000, 600000, 'https://www.nhtsa.gov/vehicle/2020/CHEVROLET/SILVERADO%201500 (owner complaints); cost range is an assumption'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'Transmission shudder', 'Shake at 25 to 50 mph under light throttle', 30000, 350000, 'https://www.nhtsa.gov/vehicle/2020/CHEVROLET/SILVERADO%201500 (owner complaints); cost range is an assumption'),
  ('2020-chevrolet-silverado-1500-5.3-4wd', 'A/C condenser leak', 'A/C blows warm after a few months', 80000, 150000, 'https://www.nhtsa.gov/vehicle/2020/CHEVROLET/SILVERADO%201500 (owner complaints); cost range is an assumption'),
  ('2021-toyota-rav4-hybrid-awd', '12V battery drain', 'Car will not show READY after sitting a few days', 15000, 35000, 'https://www.nhtsa.gov/vehicle/2021/TOYOTA/RAV4%20HYBRID (owner complaints); cost range is an assumption'),
  ('2021-toyota-rav4-hybrid-awd', 'Fuel tank will not fill completely', 'Pump clicks off early, range lower than expected', 0, 150000, 'https://www.nhtsa.gov/vehicle/2021/TOYOTA/RAV4%20HYBRID (owner complaints); cost range is an assumption'),
  ('2021-toyota-rav4-hybrid-awd', 'Hybrid inverter coolant pump', 'Hybrid system warning light', 50000, 120000, 'https://www.nhtsa.gov/vehicle/2021/TOYOTA/RAV4%20HYBRID (owner complaints); cost range is an assumption');
